import { attachRollsToChatData } from "./chat-roll-helpers.js";
import { applyRollModeToChatData } from "./roll-mode-helpers.js";

const SIEGE_RESULT_TEMPLATE = "systems/castles-and-crusades/templates/chat/siege-roll-result.html";

function defaultCreateChatMessage(chatData) {
  return globalThis.ChatMessage.create(chatData);
}

function defaultGetSpeaker(actor) {
  return globalThis.ChatMessage.getSpeaker({ actor });
}

function defaultLocalize(key) {
  return globalThis.game?.i18n?.localize(key) ?? key;
}

function defaultRenderTemplate(template, data) {
  return globalThis.foundry.applications.handlebars.renderTemplate(template, data);
}

export function buildSiegeChallengeClass({
  challengeBase = 0,
  challengeLevel = 0,
  challengeModifier = 0,
} = {}) {
  return Number(challengeBase ?? 0) + Number(challengeLevel ?? 0) + Number(challengeModifier ?? 0);
}

export function buildSiegeCheckResult(rollTotal, challengeClass) {
  const isSuccess = Number(rollTotal ?? 0) >= Number(challengeClass ?? 0);
  return {
    isSuccess,
    resultClass: isSuccess ? "success" : "failure",
    resultLabelKey: isSuccess ? "TLGCC.Success" : "TLGCC.Failure",
  };
}

export async function createSiegeCheckChatCard({
  actor,
  abilityLabel,
  isPrime = false,
  challengeBase = 0,
  challengeLevel = 0,
  challengeModifier = 0,
  roll,
  rollMode,
  createChatMessage = defaultCreateChatMessage,
  getSpeaker = defaultGetSpeaker,
  localize = defaultLocalize,
  renderTemplate = defaultRenderTemplate,
} = {}) {
  const challengeClass = buildSiegeChallengeClass({
    challengeBase,
    challengeLevel,
    challengeModifier,
  });
  const result = buildSiegeCheckResult(roll?.total, challengeClass);
  const rollHtml = await roll.render();
  const content = await renderTemplate(SIEGE_RESULT_TEMPLATE, {
    abilityLabel,
    isPrime,
    primeText: isPrime ? "true" : "false",
    rollHtml,
    challengeBase,
    challengeLevel,
    challengeModifier,
    challengeClass,
    resultLabel: localize(result.resultLabelKey),
    resultClass: result.resultClass,
  });

  const chatData = attachRollsToChatData(applyRollModeToChatData({
    speaker: getSpeaker(actor),
    flavor: `Roll: <b>${abilityLabel} ${localize("TLGCC.SiegeCheck")}</b>`,
    content,
  }, rollMode), roll);

  return createChatMessage(chatData);
}
