export function attachRollsToChatData(chatData, rolls = []) {
  const rollList = (Array.isArray(rolls) ? rolls : [rolls]).filter(Boolean);
  if (!rollList.length) return chatData;

  chatData.rolls = [
    ...(Array.isArray(chatData.rolls) ? chatData.rolls : []),
    ...rollList,
  ];
  return chatData;
}
