const LEGACY_ROLL_MODE_TO_MESSAGE_MODE = {
  blindroll: "blind",
  gmroll: "gm",
  publicroll: "public",
  selfroll: "self",
};

const MESSAGE_MODE_TO_LEGACY_ROLL_MODE = {
  blind: "blindroll",
  gm: "gmroll",
  public: "publicroll",
  self: "selfroll",
};

const VALID_LEGACY_ROLL_MODES = new Set(Object.keys(LEGACY_ROLL_MODE_TO_MESSAGE_MODE));
const VALID_MESSAGE_MODES = new Set(Object.keys(MESSAGE_MODE_TO_LEGACY_ROLL_MODE));

export function getFoundryGeneration() {
  const releaseGeneration = Number(globalThis.game?.release?.generation);
  if (Number.isFinite(releaseGeneration)) return releaseGeneration;

  const version = `${globalThis.game?.release?.version ?? globalThis.game?.version ?? ""}`;
  const majorVersion = Number.parseInt(version.split(".")[0], 10);
  return Number.isFinite(majorVersion) ? majorVersion : 14;
}

export function normalizeLegacyRollMode(rollMode, fallback = "publicroll") {
  const normalized = `${rollMode ?? ""}`.trim();
  if (VALID_LEGACY_ROLL_MODES.has(normalized)) return normalized;
  if (MESSAGE_MODE_TO_LEGACY_ROLL_MODE[normalized]) return MESSAGE_MODE_TO_LEGACY_ROLL_MODE[normalized];

  const fallbackMode = `${fallback ?? ""}`.trim();
  if (VALID_LEGACY_ROLL_MODES.has(fallbackMode)) return fallbackMode;
  if (MESSAGE_MODE_TO_LEGACY_ROLL_MODE[fallbackMode]) return MESSAGE_MODE_TO_LEGACY_ROLL_MODE[fallbackMode];
  return "publicroll";
}

export function normalizeMessageMode(rollMode, fallback = "publicroll") {
  const normalized = `${rollMode ?? ""}`.trim();
  if (VALID_MESSAGE_MODES.has(normalized)) return normalized;
  if (LEGACY_ROLL_MODE_TO_MESSAGE_MODE[normalized]) return LEGACY_ROLL_MODE_TO_MESSAGE_MODE[normalized];

  const fallbackMode = `${fallback ?? ""}`.trim();
  if (VALID_MESSAGE_MODES.has(fallbackMode)) return fallbackMode;
  if (LEGACY_ROLL_MODE_TO_MESSAGE_MODE[fallbackMode]) return LEGACY_ROLL_MODE_TO_MESSAGE_MODE[fallbackMode];
  return "public";
}

export function normalizeRollMode(rollMode, fallback = "publicroll") {
  return normalizeMessageMode(rollMode, fallback);
}

export function applyRollModeToChatData(chatData, rollMode, {
  fallback = "publicroll",
  currentUserId = globalThis.game?.user?.id,
  getWhisperRecipients = (role) => globalThis.ChatMessage?.getWhisperRecipients(role) ?? [],
} = {}) {
  const legacyRollMode = normalizeLegacyRollMode(rollMode, fallback);

  if (legacyRollMode === "selfroll") {
    chatData.whisper = currentUserId ? [currentUserId] : [];
    chatData.blind = false;
    return chatData;
  }

  if (["gmroll", "blindroll"].includes(legacyRollMode)) {
    chatData.whisper = getWhisperRecipients("GM");
    chatData.blind = legacyRollMode === "blindroll";
    return chatData;
  }

  chatData.whisper = [];
  chatData.blind = false;
  return chatData;
}

export function getRollToMessageOptions(
  rollMode,
  fallback = "publicroll",
  { foundryGeneration = getFoundryGeneration() } = {},
) {
  if (Number(foundryGeneration) >= 14) {
    return {
      messageMode: normalizeMessageMode(rollMode, fallback),
    };
  }

  return {
    rollMode: normalizeLegacyRollMode(rollMode, fallback),
  };
}
